package in.kabadiwala.connect.repository; import in.kabadiwala.connect.model.Payment; import org.springframework.data.mongodb.repository.MongoRepository; public interface PaymentRepository extends MongoRepository<Payment,String>{ java.util.Optional<Payment> findByPaymentId(String paymentId); java.util.Optional<Payment> findTopByTransactionIdOrderByCreatedAtDesc(String transactionId);}